from collections import deque

H, W = 20, 20
rect_info = [
    ("Top", 0, 4, 11, 15), ("Left", 1, 9, 1, 9), 
    ("Mid", 7, 11, 13, 17), ("Bot", 12, 18, 5, 11)
]

def fill_not_connected_to_interior_2():
    """Fill enclosed 0s EXCEPT those connected (any path of 0s) to interior 2"""
    output = [row[:] for row in test_input]

    for name, r1, r2, c1, c2 in rect_info:
        # Find interior 2 positions
        int2_positions = set((rr, cc) for rr in range(r1+1, r2) for cc in range(c1+1, c2) 
                            if test_input[rr][cc] == 2)

        if not int2_positions:
            continue

        # Mark all 0s reachable FROM interior 2s via BFS
        reachable_from_int2 = {p: False for p in [(r,c) for r in range(r1+1, r2) for c in range(c1+1, c2)]}
        queue = deque()

        for ir, ic in int2_positions:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = ir+dr, ic+dc
                if r1+1 <= nr < r2 and c1+1 <= nc < c2 and test_input[nr][nc] == 0:
                    reachable_from_int2[(nr,nc)] = True
                    queue.append((nr, nc))

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (r1+1 <= nr < r2 and c1+1 <= nc < c2):
                    if not reachable_from_int2[(nr,nc)] and test_input[nr][nc] == 0:
                        reachable_from_int2[(nr,nc)] = True
                        queue.append((nr, nc))

        # Find ALL enclosed 0s (standard flood fill outside)
        visited_edge = [[False]*W for _ in range(H)]
        edge_queue = deque()
        for r in range(H):
            for c in [0, W-1]:
                if test_input[r][c] == 0:
                    visited_edge[r][c] = True
                    edge_queue.append((r, c))
        for c in range(W):
            for r in [0, H-1]:
                if test_input[r][c] == 0:
                    visited_edge[r][c] = True
                    edge_queue.append((r, c))

        while edge_queue:
            r, c = edge_queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and not visited_edge[nr][nc]:
                    if test_input[nr][nc] == 0:
                        visited_edge[nr][nc] = True
                        edge_queue.append((nr, nc))

        enclosed = {(r,c) for r in range(H) for c in range(W) 
                   if test_input[r][c] == 0 and not visited_edge[r][c]}

        # Fill enclosed 0s that are NOT reachable from interior 2
        for pos in enclosed:
            r, c = pos
            if r1+1 <= r < r2 and c1+1 <= c < c2:
                if not reachable_from_int2[pos]:
                    output[r][c] = 8

    return output

fill_result = fill_not_connected_to_interior_2()
print("=== FILL ONLY ENCLOSURE NOT CONNECTED TO INTERIOR-2 ===")

for name, r1, r2, c1, c2 in [("Top",0,4,11,15), ("Mid",7,11,13,17)]:
